fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Pre-allocate enough space for both vectors
    let mut result = Vec::with_capacity(arr.len() + values.len());

    // Extend the result with the elements from the first vector
    result.extend(arr);

    // Extend the result with the elements from the second vector
    result.extend(values);

    result
}

